examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    MonarchMessageComposer(
        {{label}},
        text: $text,
        placeholder: {{placeholder}},
        replyTo: replying ? MonarchMessageComposerReply(author: {{replyTo.author}}, excerpt: {{replyTo.excerpt}}) : nil,
        showsEmojiButton: false,
        showsFormatting: true,
        onDismissReply: { replying = false }
    ) {
        EmptyView()
    } actions: {
        MonarchButton({{emoji}}, variant: .ghost, size: .sm) { text += {{emoji}} }
    } onSend: { _ in
        replying = false
    }
    Text("Enter to send, Shift+Enter for a new line")
        .monarchTextStyle(.caption)
        .foregroundStyle(theme.colors.textMuted)
}

examples.setupTemplate:
